const resp = $.steps.addEntry.response || {};
const data = resp.data || {};
const id = data.id || {};

return {
  entryId: id.entry_id || '',
  listId: id.list_id || '',
  parentRecordId: data.parent_record_id || $.input.parentRecordId,
  parentObject: data.parent_object || $.input.parentObject,
  createdAt: data.created_at || '',
  summary: id.entry_id
    ? `Added ${$.input.parentObject} record ${$.input.parentRecordId} to list ${$.input.list}`
    : 'Failed to add record to list'
};
